CREATE TABLE game_entitlement (id BIGINT NOT NULL AUTO_INCREMENT,user_id BIGINT NOT NULL,edition_id BIGINT NOT NULL,source_order_id BIGINT NULL,status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'active',granted_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),active_entitlement TINYINT GENERATED ALWAYS AS(IF(status='active',1,NULL)) STORED,PRIMARY KEY(id),CONSTRAINT uk_game_entitlement_owner UNIQUE(user_id,edition_id,active_entitlement),KEY idx_game_entitlement_edition(edition_id),KEY idx_game_entitlement_source_order(source_order_id),CONSTRAINT ck_game_entitlement_status CHECK(status IN ('active','revoked')),CONSTRAINT fk_game_entitlement_user FOREIGN KEY(user_id) REFERENCES user_account(id) ON DELETE CASCADE,CONSTRAINT fk_game_entitlement_edition FOREIGN KEY(edition_id) REFERENCES game_edition(id) ON DELETE RESTRICT,CONSTRAINT fk_game_entitlement_source_order FOREIGN KEY(source_order_id) REFERENCES purchase_order(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
